function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    const chave = JSON.stringify(args);
    if (cache.has(chave)) {
      return cache.get(chave);
    }
    const resultado = fn(...args);
    cache.set(chave, resultado);
    return resultado;
  };
}

function calcularFatorial(n) {
  console.log(`A calcular fatorial de ${n}...`);
  let resultado = 1;
  for (let i = 2; i <= n; i++) {
    resultado *= i;
  }
  return resultado;
}

const fatorialMemo = memoize(calcularFatorial);

fatorialMemo(20); // executa o cálculo e imprime "A calcular fatorial de 20..."
fatorialMemo(20); // devolve o valor da cache, sem imprimir nada

function debounce(fn, atraso = 300) {
  let temporizador;
  return function (...args) {
    clearTimeout(temporizador);
    temporizador = setTimeout(() => fn.apply(this, args), atraso);
  };
}

const campoPesquisa = document.querySelector('#pesquisa');

const pesquisarNaAPI = debounce((termo) => {
  console.log(`A pesquisar por: ${termo}`);
}, 400);

campoPesquisa.addEventListener('input', (evento) => {
  pesquisarNaAPI(evento.target.value);
});

function throttle(fn, intervalo = 200) {
  let bloqueado = false;
  return function (...args) {
    if (bloqueado) return;
    bloqueado = true;
    fn.apply(this, args);
    setTimeout(() => {
      bloqueado = false;
    }, intervalo);
  };
}

const aoFazerScroll = throttle(() => {
  console.log('Posição atual do scroll:', window.scrollY);
}, 200);

window.addEventListener('scroll', aoFazerScroll);

const lista = Array.from({ length: 100000 }, (_, i) => i);
const conjunto = new Set(lista);
const alvos = [10, 5000, 99999, -1, 50000];

console.time('array.includes');
let encontradosArray = 0;
for (const alvo of alvos) {
  if (lista.includes(alvo)) encontradosArray++;
}
console.timeEnd('array.includes'); // cresce com o tamanho de "lista": O(n) por verificação

console.time('set.has');
let encontradosSet = 0;
for (const alvo of alvos) {
  if (conjunto.has(alvo)) encontradosSet++;
}
console.timeEnd('set.has'); // praticamente constante: O(1) por verificação

console.log(encontradosArray, encontradosSet); // 4 4

// Versão pouco eficiente: recria a regex e recalcula o sufixo em cada iteração
function contarEmailsValidos(emails, dominioPermitido) {
  let total = 0;
  for (let i = 0; i < emails.length; i++) {
    const regexEmail = /^[\w.+-]+@[\w-]+\.[a-z]{2,}$/i;
    const sufixo = `@${dominioPermitido}`;
    if (regexEmail.test(emails[i]) && emails[i].endsWith(sufixo)) {
      total++;
    }
  }
  return total;
}

// Versão otimizada: o que não depende do email atual sai do ciclo
function contarEmailsValidosOtimizado(emails, dominioPermitido) {
  const regexEmail = /^[\w.+-]+@[\w-]+\.[a-z]{2,}$/i; // criada uma única vez
  const sufixo = `@${dominioPermitido}`; // não depende do email atual

  let total = 0;
  for (const email of emails) {
    if (regexEmail.test(email) && email.endsWith(sufixo)) {
      total++;
    }
  }
  return total;
}

exercises.statement:
Implemente uma função genérica memoize(fn) que recebe uma função de um único argumento e devolve uma nova função que guarda os resultados já calculados numa cache (por exemplo, um Map), devolvendo o valor da cache quando o mesmo argumento é pedido de novo. Depois, aplique memoize à função seguinte, que verifica de forma propositadamente lenta se um número é primo (testa a divisibilidade por todos os inteiros entre 2 e a raiz quadrada de n):

function ehPrimo(n) {
  if (n < 2) return false;
  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) return false;
  }
  return true;
}

Confirme que, ao chamar a versão memoizada duas vezes com o mesmo valor de n, o corpo de ehPrimo só é executado na primeira chamada (pode confirmar isto colocando um console.log dentro de ehPrimo).

exercises.solution_code:
function memoize(fn) {
  const cache = new Map();
  return function (n) {
    if (cache.has(n)) {
      return cache.get(n);
    }
    const resultado = fn(n);
    cache.set(n, resultado);
    return resultado;
  };
}

function ehPrimo(n) {
  console.log(`A verificar ${n}...`);
  if (n < 2) return false;
  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) return false;
  }
  return true;
}

const ehPrimoMemo = memoize(ehPrimo);

console.log(ehPrimoMemo(97919)); // imprime "A verificar 97919..." e depois o resultado
console.log(ehPrimoMemo(97919)); // resultado direto da cache, sem novo log

