exercises.statement:
A função seguinte percorre uma lista de produtos e devolve apenas os que têm um código válido (duas letras maiúsculas seguidas de quatro dígitos) e cujo preço, depois de aplicado um imposto, não ultrapassa um limite máximo:

function filtrarProdutosValidos(produtos, taxaImposto, limiteMaximo) {
  const validos = [];
  for (let i = 0; i < produtos.length; i++) {
    const regexCodigo = /^[A-Z]{2}\d{4}$/;
    const multiplicador = 1 + taxaImposto;
    const precoComImposto = produtos[i].preco * multiplicador;
    if (regexCodigo.test(produtos[i].codigo) && precoComImposto <= limiteMaximo) {
      validos.push(produtos[i]);
    }
  }
  return validos;
}

Identifique quais dos valores calculados dentro do ciclo não dependem do produto da iteração atual e reescreva a função de forma mais eficiente, sem alterar o resultado.

exercises.solution_code:
function filtrarProdutosValidos(produtos, taxaImposto, limiteMaximo) {
  const regexCodigo = /^[A-Z]{2}\d{4}$/; // não depende de i: criar uma só vez
  const multiplicador = 1 + taxaImposto;  // idem: é o mesmo em todas as iterações
  const validos = [];

  for (const produto of produtos) {
    const precoComImposto = produto.preco * multiplicador; // este sim depende do produto
    if (regexCodigo.test(produto.codigo) && precoComImposto <= limiteMaximo) {
      validos.push(produto);
    }
  }

  return validos;
}

const produtos = [
  { codigo: 'AB1234', preco: 100 },
  { codigo: 'xy9999', preco: 50 },
  { codigo: 'CD5678', preco: 200 },
];

console.log(filtrarProdutosValidos(produtos, 0.23, 150));
// [{ codigo: 'AB1234', preco: 100 }]

exercises.statement:
A função seguinte recebe duas listas de identificadores (arrays de strings) e devolve os identificadores que aparecem em ambas, usando includes dentro de um ciclo:

function encontrarComuns(listaA, listaB) {
  const comuns = [];
  for (const id of listaA) {
    if (listaB.includes(id)) {
      comuns.push(id);
    }
  }
  return comuns;
}

Para listas grandes (por exemplo, 50000 elementos cada), esta função é lenta. Reescreva encontrarComuns para ter complexidade aproximadamente O(n + m) em vez de O(n × m), produzindo exatamente o mesmo resultado que a versão original produziria, e explique num comentário no código porque é que a nova versão é mais rápida.

exercises.solution_code:
function encontrarComuns(listaA, listaB) {
  // Converter listaB num Set uma única vez: custo O(m).
  // A partir daqui, cada verificação "has" é O(1) em média,
  // em vez de percorrer listaB inteira (O(m)) para cada elemento de listaA.
  const conjuntoB = new Set(listaB);
  const comuns = [];

  for (const id of listaA) {
    if (conjuntoB.has(id)) {
      comuns.push(id);
    }
  }

  return comuns; // custo total aproximado: O(n + m), em vez de O(n × m)
}

const listaA = ['a1', 'a2', 'a3', 'a4'];
const listaB = ['a3', 'a4', 'a5'];

console.log(encontrarComuns(listaA, listaB)); // ['a3', 'a4']
